{"path":"test_chip8.js","content":"// Headless smoke test for the CHIP-8 emulator core inside the HTML file.
const fs = require('fs');
const html = fs.readFileSync('chip8_openrouter-moonshotai-kimi-k3_01.html', 'utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
if (!m) { console.error('FAIL: no <script> block'); process.exit(1); }
let src = m[1];

// ---- DOM / browser stubs ----
const noop = () => {};
const ctx2d = new Proxy({}, { get: () => noop, set: () => true });
function fakeEl() {
  return {
    getContext: () => ctx2d,
    addEventListener: noop,
    appendChild: noop,
    style: {},
    classList: { add: noop, remove: noop, toggle: noop },
    textContent: '', innerHTML: '', value: '10',
    width: 0, height: 0, disabled: false,
    querySelector: () => fakeEl(),
    files: [],
  };
}
global.document = {
  getElementById: () => fakeEl(),
  querySelector: () => fakeEl(),
  querySelectorAll: () => [],
  createElement: () => fakeEl(),
  addEventListener: noop,
  body: fakeEl(),
};
global.window = { addEventListener: noop, AudioContext: undefined, webkitAudioContext: undefined };
global.requestAnimationFrame = noop;
global.FileReader = function() { this.readAsArrayBuffer = noop; };

// Expose internals: eval in this scope, then grab via appended hook.
src += '\n;globalThis.__t = { chip8: (typeof chip8 !== "undefined") ? chip8 : null, Chip8: (typeof Chip8 !== "undefined") ? Chip8 : null, DEMO_ROM: (typeof DEMO_ROM !== "undefined") ? DEMO_ROM : null };';
eval(src);
const { chip8, Chip8, DEMO_ROM } = globalThis.__t;

let pass = 0, fail = 0;
function check(name, cond) {
  if (cond) { pass++; console.log('  ok  ' + name); }
  else { fail++; console.log('FAIL  ' + name); }
}
if (!Chip8) { console.error('FAIL: Chip8 class not found'); process.exit(1); }

// helper: build a CPU with a program loaded
function cpu(bytes, opts) {
  const c = new Chip8();
  c.loadRom(bytes);
  return c;
}
function run(c, n) { for (let i = 0; i < n; i++) c.cycle(); }

// ---- font set ----
{
  const c = new Chip8();
  check('font loaded at 0x050 (F = 0xF0,0x90,0x90,0x90,0xF0)',
    c.memory[0x50] === 0xF0 && c.memory[0x51] === 0x90 && c.memory[0x54] === 0xF0);
  check('font 0 at 0x050 first byte 0xF0', c.memory[0x50] === 0xF0);
}

// ---- 6xkk / 7xkk / 8xy4 carry / 8xy5 borrow / 8xy7 ----
{
  const c = cpu([0x60,0xFF, 0x61,0x01, 0x80,0x14, 0x80,0x15]); // V0=FF,V1=1,V0+=V1,V0-=V1
  run(c, 4);
  check('8xy4 carry: V0 wraps to 0x00', c.V[0] === 0x00);
  check('8xy4 carry: VF=1', c.V[0xF] === 1);
  check('8xy5 borrow: V0 back to 0xFF', c.V[0] === 0xFF);
  check('8xy5 no-borrow: VF=1', c.V[0xF] === 1);
}
{
  const c = cpu([0x60,0x05, 0x61,0x09, 0x80,0x15]); // V0=5,V1=9,V0-=V1
  run(c, 3);
  check('8xy5 borrow: V0=0xFC', c.V[0] === 0xFC);
  check('8xy5 borrow: VF=0', c.V[0xF] === 0);
}

// ---- shifts ----
{
  const c = cpu([0x60,0x03, 0x80,0x06, 0x80,0x0E]); // V0=3, V0>>=1, V0<<=1
  run(c, 3);
  check('8xy6: V0=1, VF=1 (lsb was 1)', c.V[0] === 1 && c.V[0xF] === 1);
  check('8xyE: V0=2, VF=0', c.V[0] === 2 && c.V[0xF] === 0);
}

// ---- jumps / calls / stack ----
{
  const c = cpu([0x22,0x08, 0x00,0x00, 0x00,0x00, 0x61,0x42, 0x00,0xEE]); // call 0x208; ...; 0x208: V1=42; ret
  run(c, 3);
  check('call: subroutine executed V1=0x42', c.V[1] === 0x42);
  check('ret: pc back at 0x202', c.pc === 0x202);
  check('stack empty after ret', c.stack.length === 0);
}

// ---- skips ----
{
  const c = cpu([0x60,0x05, 0x30,0x05, 0x61,0x01, 0x62,0x02]); // V0=5; skip if V0==5; V1=1(skipped); V2=2
  run(c, 4);
  check('3xkk skip taken: V1 untouched', c.V[1] === 0);
  check('3xkk skip taken: V2 set', c.V[2] === 2);
}

// ---- random ----
{
  const c = cpu([0xC0,0x0F]);
  c.cycle();
  check('Cxkk masked: V0 <= 0x0F', c.V[0] >= 0 && c.V[0] <= 0x0F);
}

// ---- BCD Fx33 + Fx55/Fx65 roundtrip ----
{
  const c = cpu([0x60,0xFF, 0xF0,0x33, 0xF0,0x55, 0x60,0x00, 0xF0,0x65]); // V0=255; BCD->I; save; V0=0; load
  run(c, 5);
  check('Fx33 BCD: mem[I..I+2] = 2,5,5', c.memory[c.I] === 2 && c.memory[c.I+1] === 5 && c.memory[c.I+2] === 5);
  check('Fx65 load: V0 restored to 255', c.V[0] === 255);
}

// ---- draw + collision ----
{
  // I=0x300 via Annn, sprite byte 0xFF at 0x300, draw at (0,0) twice -> collision
  const c = cpu([0xA3,0x00, 0x60,0x00, 0x61,0x00, 0xD0,0x11, 0xD0,0x11]);
  c.memory[0x300] = 0xFF;
  run(c, 4);
  check('Dxyn first draw: VF=0 (no collision), pixels set', c.V[0xF] === 0 && c.display[0] === 1);
  run(c, 1);
  check('Dxyn second draw: VF=1 (collision), pixels cleared', c.V[0xF] === 1 && c.display[0] === 0);
}

// ---- key wait Fx0A ----
{
  const c = cpu([0xF0,0x0A, 0x61,0x09]);
  run(c, 3);
  check('Fx0A blocks until key press (pc still at 0x200)', c.pc === 0x200);
  c.keys[5] = true;
  c.cycle();
  check('Fx0A stores pressed key in V0', c.V[0] === 5 && c.pc === 0x202);
}

// ---- key skips Ex9E / ExA1 ----
{
  const c = cpu([0x60,0x04, 0xE0,0x9E, 0x61,0x01, 0x62,0x02]);
  c.keys[4] = true;
  run(c, 4);
  check('Ex9E skips when key down', c.V[1] === 0 && c.V[2] === 2);
}

// ---- timers ----
{
  const c = cpu([0x60,0x02, 0xF0,0x15, 0x60,0x03, 0xF0,0x18]);
  run(c, 4);
  check('Fx15 sets delay timer', c.delayTimer === 2);
  check('Fx18 sets sound timer', c.soundTimer === 3);
  if (typeof c.tickTimers === 'function') {
    c.tickTimers();
    check('tickTimers decrements both', c.delayTimer === 1 && c.soundTimer === 2);
  } else {
    check('tickTimers method exists', false);
  }
  // Fx07 reads delay timer
  const c2 = cpu([0x60,0x07, 0xF0,0x15, 0xF1,0x07]);
  run(c2, 3);
  check('Fx07 reads delay timer into V1', c2.V[1] === 7);
}

// ---- Fx1E add to I ----
{
  const c = cpu([0xA3,0x00, 0x60,0x10, 0xF0,0x1E]);
  run(c, 3);
  check('Fx1E: I += V0', c.I === 0x310);
}

// ---- Fx29 font char address ----
{
  const c = cpu([0x60,0x0A, 0xF0,0x29]);
  run(c, 2);
  check('Fx29: I = 0x050 + A*5 = 0x07D', c.I === 0x050 + 0x0A * 5);
}

// ---- demo ROM runs without crashing and draws something ----
{
  check('DEMO_ROM exists and is a non-empty array', Array.isArray(DEMO_ROM) && DEMO_ROM.length > 0);
  const c = new Chip8();
  c.loadRom(DEMO_ROM);
  let err = null;
  try { for (let i = 0; i < 5000; i++) { c.cycle(); if (i % 60 === 0 && typeof c.tickTimers === 'function') c.tickTimers(); } }
  catch (e) { err = e; }
  check('demo ROM runs 5000 cycles without exception', err === null);
  if (err) console.log('   error: ' + err.message);
  const lit = c.display.reduce((a, b) => a + (b ? 1 : 0), 0);
  check('demo ROM drew pixels on display (' + lit + ' lit)', lit > 0);
  // react to a key: press key 6 (move right) and run more
  c.keys[6] = true;
  try { for (let i = 0; i < 2000; i++) { c.cycle(); if (i % 60 === 0 && typeof c.tickTimers === 'function') c.tickTimers(); } } catch (e) { err = e; }
  check('demo ROM survives key input', err === null);
}

// ---- disassembler sanity (if exposed) ----
{
  const d = globalThis.__t.disassemble || (typeof disassemble !== 'undefined' ? disassemble : null);
  if (d) {
    check('disassemble 0x00E0 -> CLS-ish', /cls|clear/i.test(d(0x00E0)));
    check('disassemble 0x1234 -> JP 0x234', /1?234|23 4|0x234/i.test(d(0x1234)));
  } else {
    console.log('  --  disassemble not exposed globally (ok if internal)');
  }
}

console.log('\n' + pass + ' passed, ' + fail + ' failed');
process.exit(fail ? 1 : 0);
"}

